```java
// ─── File: S3SecurityDemo.java ───
// This file contains multiple classes for the runnable demo.
// In a real project each class would be in its own file.
package com.bank.s3sec;

import java.util.*;
import java.util.logging.*;

public class S3SecurityDemo {
    private static final Logger log = Logger.getLogger("S3Security");

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BucketSecurity security = new BucketSecurity(
                true,                                      // blockPublicAccess
                Set.of("role/statement-service"),          // allowed principals
                true,                                      // requireTls
                "SSE-KMS");                                 // encryption at rest
        SecurityAuditor auditor = new SecurityAuditor(security);

        AccessRequest legit = new AccessRequest("role/statement-service", true, true);
        AccessRequest publicUser = new AccessRequest("anonymous", true, false);
        AccessRequest insecure = new AccessRequest("role/statement-service", false, true);

        log.info(() -> "Legit service request: " + auditor.evaluate(legit));
        log.severe(() -> "Public internet request: " + auditor.evaluate(publicUser));
        log.warning(() -> "Non-TLS request: " + auditor.evaluate(insecure));
        log.info(() -> "Encryption at rest: " + security.encryption() + " (keys audited in CloudTrail)");
    }
}

// ─── Would be in SecurityAuditor.java ───
class SecurityAuditor {
    private final BucketSecurity security;
    SecurityAuditor(BucketSecurity security) { this.security = security; }

    // Layered checks: public access, principal allow-list, TLS requirement.
    String evaluate(AccessRequest req) {
        if (security.blockPublicAccess() && "anonymous".equals(req.principal())) {
            return "DENIED — Block Public Access overrides any policy";
        }
        if (!security.allowedPrincipals().contains(req.principal())) {
            return "DENIED — principal not in least-privilege allow-list";
        }
        if (security.requireTls() && !req.overTls()) {
            return "DENIED — request not over TLS (aws:SecureTransport=false)";
        }
        return "ALLOWED — GetObject over TLS, data decrypted via KMS";
    }
}

// ─── Would be in BucketSecurity.java ───
class BucketSecurity {
    private final boolean blockPublicAccess;
    private final Set<String> allowedPrincipals;
    private final boolean requireTls;
    private final String encryption;
    BucketSecurity(boolean blockPublicAccess, Set<String> allowedPrincipals,
                   boolean requireTls, String encryption) {
        this.blockPublicAccess = blockPublicAccess;
        this.allowedPrincipals = allowedPrincipals;
        this.requireTls = requireTls;
        this.encryption = encryption;
    }
    boolean blockPublicAccess() { return blockPublicAccess; }
    Set<String> allowedPrincipals() { return allowedPrincipals; }
    boolean requireTls() { return requireTls; }
    String encryption() { return encryption; }
}

// ─── Would be in AccessRequest.java ───
class AccessRequest {
    private final String principal;
    private final boolean overTls;
    private final boolean encryptedUpload;
    AccessRequest(String principal, boolean overTls, boolean encryptedUpload) {
            this.principal = principal;
            this.overTls = overTls
            this.encryptedUpload = encryptedUpload;
    }
    String principal() { return principal; }
    boolean overTls() { return overTls; }
    boolean encryptedUpload() { return encryptedUpload; }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                r.getMillis(), r.getLevel(), r.getMessage());
    }
}
